{
  "requirements": [
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "The maximum amount of data that can be refueled is 2GB.",
      "requirement": "The `gb_amount` must not exceed 2GB for the refueling action."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "To refuel data you should: ... Apply the refueled data to the line associated with the phone number the user provided.",
      "requirement": "The `line_id` must correspond to the line associated with the phone number provided by the user for the refueling action."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "To refuel data you should: ... Ask them how much data they want to refuel. Confirm the price. Apply the refueled data...",
      "requirement": "The user must have explicitly confirmed the amount of data (2GB) and the price before applying the refueling."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "Each plan specifies ... data refueling price per GB.",
      "requirement": "The refueling price must be calculated based on the plan's specified price per GB for the `line_id` being refueled."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "If the user's data usage for a line exceeds the plan's data limit, data connectivity will be lost.",
      "requirement": "The action must address the issue of the user's data limit being exceeded (15.1GB > 15.0GB) for the line."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "If the user's data usage for a line associated with the phone number the user provided exceeds the plan's data limit, data connectivity will be lost. The user has 2 options: Change to a plan with more data. Add more data to the line by 'refueling' data at a price per GB specified by the plan.",
      "requirement": "The refueling action must be one of the two valid options provided to the user for resolving exceeded data limits."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q7",
      "policy_quote": "You are a customer service agent that helps the user according to the <policy> provided below.",
      "requirement": "The action must strictly adhere to the policy guidelines for assisting users, including confirming user intent and providing valid options."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You can add more data to the line by 'refueling' data at a price per GB specified by the plan.",
      "requirement": "The refueling must be applied to the line (`line_id`) and must charge the user based on the plan's refueling rate per GB."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You should only make one tool call at a time, and if you make a tool call, you should not respond to the user simultaneously.",
      "requirement": "The refueling action must be executed as a standalone tool call without simultaneous user communication."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You should deny user requests that are against this policy.",
      "requirement": "The action must not proceed if the user's request violates any policy (e.g., exceeding allowed refueling limits or unauthorized changes)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You should transfer the user to a human agent if and only if the request cannot be handled within the scope of your actions.",
      "requirement": "The refueling action must not be attempted if it cannot be completed within the assistant's allowed actions (e.g., system errors or missing permissions)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q10",
      "policy_quote": "You should try your best to resolve the issue for the user before transferring the user to a human agent.",
      "requirement": "The refueling action must be the final attempt to resolve the user's issue (exceeded data limit) before escalating to a human agent."
    }
  ]
}
